import {createGardenUI} from './garden-ui.js';
import {crops,applyLife,freshLife} from './life-state.js';
export function createLifeUI({context,replace,save,refresh,cloud,modal,close,toast,handlers,request,dock,endOutdoor,setMode}){
 const icons={rose:'🌹',tulip:'🌷',sunflower:'🌻',daisy:'🌼',lavender:'🪻',hydrangea:'💠',lily:'⚜',tomato:'🍅',carrot:'🥕',strawberry:'🍓'};let busy=false;
 const c=()=>context(),button=(action,label,extra='')=>`<button class="pill" data-do="${action}" ${extra}>${label}</button>`;
 async function action(data){if(busy)return false;busy=true;document.querySelectorAll('#panel-body button').forEach(b=>b.disabled=true);try{if(cloud){if(!await cloud.life({world:c().world,...data}))return false}else{const next=structuredClone(c().state);applyLife(next,c().actor,true,{world:c().world,...data});replace(next);save();refresh()}if(!['plant','water','harvest'].includes(data.type))toast('已经保存，也记进手账了。');return true}catch(e){toast(e.message);return false}finally{busy=false;document.querySelectorAll('#panel-body button').forEach(b=>b.disabled=false)}}
 const gardenUI=createGardenUI({context,action,close,toast});
 function garden(){if((c().state.worlds[c().world].theme??c().world)!==0)return toast('这个星球没有花园。');gardenUI.open()}
 function vase(){const flowers=c().state.worlds[c().world].life?.vase||[],bag=c().state.worlds[c().actor].life?.flowers||{};modal('vase','FLOWERS FROM OUR GARDEN','餐桌上的一束花',`<p class="subtle">花瓶里有 ${flowers.length} / 8 枝花。插好后，关上面板就能在一层桌上看见。</p><div class="bouquet-preview">${flowers.map(f=>icons[f]).join(' ')||'还在等第一朵花'}</div><div class="chips">${Object.entries(crops).filter(([id,v])=>v.flower).map(([id,v])=>button('life-vase',`${icons[id]} ${v.name} × ${bag[id]||0}`,`data-crop="${id}" ${!bag[id]||flowers.length>=8?'disabled':''}`)).join('')}</div>${flowers.length?button('life-clear','整理旧花'):''}<p class="subtle">整理会移走花瓶中的旧花，不退回鲜花收藏。</p>`)}
 function wardrobe(){c().visual?.wardrobe(true);const outfit=c().state.worlds[c().actor].life?.outfit||'plain';modal('wardrobe','A LITTLE COLOR TODAY','二层的小衣柜',`<p class="subtle">选好围巾，带着喜欢的颜色出门。</p><div class="room-list">${[['plain','日常装扮'],['mint','薄荷围巾'],['amber','暖橘围巾']].map(([id,n])=>button('life-outfit',(outfit===id?'✓ ':'')+n,`data-outfit="${id}"`)).join('')}</div>`)}
 function bathroom(){modal('bathroom','TAKE CARE OF YOURSELF','二层洗手间','<div class="form-actions">'+button('life-wash','洗洗手','data-kind="hands"')+button('life-wash','刷牙洗漱','data-kind="brush"')+'</div>')}
 let shotLock=false;
 function basketball(){close();if(!c().visual?.basket())return;setMode('basket');dock('<div class="dock-heading"><span>🏀 晚风篮球场</span><button data-outdoor="leave" aria-label="离开球场">×</button></div><details class="help-details"><summary>怎么玩</summary><p>指针进入绿色区域时投篮。</p></details><div class="shot-meter"><span></span><i id="shot-pointer"></i></div><div class="dock-actions"><button id="shoot-ball">投篮 ↗</button><small id="shot-result"></small></div>');document.querySelector('#shoot-ball').onclick=async()=>{if(shotLock)return;const power=(Math.sin(performance.now()/520)+1)/2,result=c().visual?.shoot(power);if(!result)return;shotLock=true;const b=document.querySelector('#shoot-ball');b.disabled=true;const outcome=document.querySelector('#shot-result');outcome.textContent='篮球飞向篮筐…';setTimeout(()=>{if(outcome.isConnected)outcome.textContent=result.made?'进球了！漂亮的一球 ♡':'擦过篮筐，再试一次吧';},1150);await action({type:'basket',made:result.made});setTimeout(()=>{shotLock=false;if(b.isConnected)b.disabled=false},1800)}}
 setInterval(()=>{const p=document.querySelector('#shot-pointer');if(p)p.style.left=((Math.sin(performance.now()/520)+1)*50)+'%'},80);
 for(const name of ['garden','basketball','bathroom','wardrobe','vase'])handlers[name]=()=>request(name);
 handlers['life-vase']=async b=>{await action({type:'vase',crop:b.dataset.crop});vase()};handlers['life-clear']=async()=>{await action({type:'clear-vase'});vase()};
 handlers['life-outfit']=async b=>{await action({type:'outfit',outfit:b.dataset.outfit});wardrobe()};
 handlers['life-wash']=async b=>{if(await action({type:'wash',kind:b.dataset.kind})){close();c().visual?.wash()}};
 return {hideGarden:()=>gardenUI.hide(),show(name){if(name==='garden-leave'){gardenUI.hide();return true}if(/^garden-plot-[0-5]$/.test(name)){gardenUI.open(Number(name.slice(-1)));return true}const fn={garden,basketball,bathroom,wardrobe,vase}[name];if(!fn)return false;fn();return true}};
}
